fn main() {
    let app = App::new("probe")
        .arg(Arg::with_name("plain").short("p").long("plain").multiple(true).overrides_with("plain").overrides_with("number"))
        .arg(Arg::with_name("paging").long("paging").takes_value(true).overrides_with("paging"))
        .arg(Arg::with_name("no-paging").short("P").long("no-paging").overrides_with("no-paging"))
        .arg(Arg::with_name("FILE").multiple(true));
    for args in [
        vec!["probe", "--paging=always", "-P", "f"],
        vec!["probe", "-P", "--paging=always", "f"],
        vec!["probe", "--paging=always", "-pp", "f"],
        vec!["probe", "-pp", "--paging=always", "f"],
        vec!["probe", "--paging=always", "-p", "-p", "f"],
        vec!["probe", "--paging=always", "-p", "f"],
    ] {
        let m = app.clone().get_matches_from(args.clone());
        println!("args={:?}", args);
        for name in ["paging", "no-paging", "plain"] {
            println!(
                "  {} present={} occ={} idx={:?}",
                name,
                m.is_present(name),
                m.occurrences_of(name),
                m.indices_of(name).map(|i| i.collect::<Vec<_>>())
            );
        }
        println!("  paging value={:?}", m.value_of("paging"));
    }
}

