fn resolve_paging_mode(&self, matches: &ArgMatches, inputs: &[Input]) -> PagingMode {
    let explicit_paging = if matches.occurrences_of("paging") > 0 {
        self.last_occurrence_index(matches, "paging")
    } else {
        None
    };
    let no_paging = self.last_occurrence_index(matches, "no-paging");
    let extra_plain = if matches.occurrences_of("plain") > 1 {
        self.last_occurrence_index(matches, "plain")
    } else {
        None
    };

    let latest = [
        explicit_paging.map(|index| (index, true)),
        no_paging.map(|index| (index, false)),
        extra_plain.map(|index| (index, false)),
    ]
    .iter()
    .filter_map(|candidate| *candidate)
    .max_by_key(|(index, _)| *index);

    match latest {
        Some((_, true)) => match self.inspect_paging_flag(matches) {
            Some("always") => PagingMode::Always,
            Some("never") => PagingMode::Never,
            Some("auto") | None => self.resolve_paging_auto(inputs),
            _ => unreachable!("other values for --paging are not allowed"),
        },
        Some((_, false)) => PagingMode::Never,
        None => self.resolve_paging_auto(inputs),
    }
}

fn last_occurrence_index(&self, matches: &ArgMatches, name: &str) -> Option<usize> {
    matches
        .indices_of(name)
        .and_then(|indices| indices.last())
}

fn resolve_paging_auto(&self, inputs: &[Input]) -> PagingMode {
    if self.inputs_include_stdin(inputs) {
        self.paging_for_stdin()
    } else if self.interactive_output {
        PagingMode::QuitIfOneScreen
    } else {
        PagingMode::Never
    }
}

